def axis(length, k, v, r):
    n = len(k)
    h = length / n
    mat = np.zeros((n, n))
    for i in range(n):
        for j in (i - 1, i + 1):
            if 0 <= j < n:
                coeff = 2 / (1 / k[i] + 1 / k[j]) / h ** 2
                mat[i, j] -= coeff
                mat[i, i] += coeff
        mat[i, i] += abs(v[i]) / h
        j = i - 1 if v[i] >= 0 else i + 1
        if 0 <= j < n:
            mat[i, j] -= abs(v[i]) / h
    for i in (0, n - 1):
        mat[i, i] += r / (1 + r * h / (2 * k[i])) / h
    return mat
